uint32_t texDictionaryAsciiPair(char first, char second) {
    for (uint32_t i = 0; i < countOf(kAsciiPairs); ++i) {
        if (kAsciiPairs[i][0] == first && kAsciiPairs[i][1] == second)
            return 0x320 + i;
    }
    return 0;
}

TexOperatorCategory texDictionaryCategory(uint32_t key, TexForm form) {
    uint32_t wanted = uint32_t(form) << 18 | key;
    uint32_t at = upperBound(Span(kRunFirst), wanted);
    if (at == 0 || wanted - kRunFirst[at - 1] > kRunLength[at - 1])
        return TexOperatorCategory_Default;
    return kRunCategory[at - 1];
}

TexCategoryValues texCategoryValues(TexOperatorCategory category) {
    return kCategoryValues[category];
}

bool texIsInlineAxis(uint32_t codePoint) {
    uint32_t at = lowerBound(Span(kInlineAxis), codePoint);
    return at != countOf(kInlineAxis) && kInlineAxis[at] == codePoint;
}

